// Varsayilan paylasim gorseli (og:image) — sabit olarak koda gömülü.
// Statik dosya klasör yapısına (public/, dist/, vb.) hiçbir şekilde bağımlı
// değildir; bu yüzden vercel.json'daki rewrite kurallarından etkilenmez ve
// içerik türü (Content-Type) her zaman doğru şekilde elle ayarlanır. Şiirin
// kendi görseli yoksa veya Firestore'a ulaşılamıyorsa postPreview.js bu
// endpoint'i kullanır.
const IMAGE_BASE64 = "";

let cachedBuffer = null;
function buffer() {
  if (!cachedBuffer) cachedBuffer = Buffer.from(IMAGE_BASE64, "base64");
  return cachedBuffer;
}

export default async function handler(req, res) {
  try {
    if (req.method !== "GET" && req.method !== "HEAD") {
      res.setHeader("Allow", "GET, HEAD");
      return res.status(405).send("Method Not Allowed");
    }
    const buf = buffer();
    res.setHeader("Content-Type", "image/jpeg");
    res.setHeader("Content-Length", String(buf.length));
    res.setHeader("Cache-Control", "public, max-age=31536000, immutable");
    res.setHeader("X-Content-Type-Options", "nosniff");
    if (req.method === "HEAD") return res.status(200).end();
    return res.status(200).send(buf);
  } catch (e) {
    console.error("og-default.js HATASI", e);
    return res.status(500).send("Varsayilan gorsel sunulamadi.");
  }
}
